package net.hivel.islandsrpg.gui;
import net.hivel.islandsrpg.IslandsRPGPlugin; import net.hivel.islandsrpg.island.Island; import net.hivel.islandsrpg.util.*; import org.bukkit.*; import org.bukkit.entity.Player; import org.bukkit.event.inventory.InventoryClickEvent; import org.bukkit.inventory.Inventory; import java.util.*;
public class IslandsGui { private final IslandsRPGPlugin p; private final Map<Integer,String> slots=new HashMap<>(); public IslandsGui(IslandsRPGPlugin p){this.p=p;} public void open(Player pl){Inventory inv=Bukkit.createInventory(null,27,ColorUtil.color("&8ɪꜱʟᴀɴᴅꜱ")); slots.clear(); int slot=10; var d=p.data().get(pl); for(Island i:p.islands().all()){boolean ok=p.islands().canUse(d,i); inv.setItem(slot,new ItemBuilder(ok?i.icon():Material.BARRIER).name(i.displayName()).lore(List.of("&7ʟᴇᴠᴇʟ: &f"+i.requiredLevel(), ok?"&aᴜɴʟᴏᴄᴋᴇᴅ":"&cʟᴏᴄᴋᴇᴅ","&eᴄʟɪᴄᴋ ᴛᴏ ᴛᴇʟᴇᴘᴏʀᴛ")).build()); slots.put(slot++,i.id());} pl.openInventory(inv);} public void click(InventoryClickEvent e){e.setCancelled(true); if(e.getWhoClicked() instanceof Player pl && slots.containsKey(e.getSlot())) p.islands().visit(pl,slots.get(e.getSlot()));} }
